import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.BAQ5ZYJQ.js";const k=JSON.parse('{"title":"Let it run: --batch and attach","description":"","frontmatter":{},"headers":[],"relativePath":"guide/detached.md","filePath":"guide/detached.md","lastUpdated":1795160929000}'),n={name:"guide/detached.md"};function h(o,a,r,l,d,p){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="let-it-run-batch-and-attach" tabindex="-1">Let it run: <code>--batch</code> and <code>attach</code> <a class="header-anchor" href="#let-it-run-batch-and-attach" aria-label="Permalink to &quot;Let it run: \`--batch\` and \`attach\`&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # submitted; the shell is yours again</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                      # later: how it is going</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attach</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                      # follow a command whose connection was lost</span></span></code></pre></div><p>Two ways to stop watching a run without stopping it. <code>--batch</code> launches the work and gives the shell back at once. A command you wait for keeps running when your laptop closes, and <code>errand attach</code> picks it up again.</p><h2 id="close-the-laptop" tabindex="-1">Close the laptop <a class="header-anchor" href="#close-the-laptop" aria-label="Permalink to &quot;Close the laptop&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cluster</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> train.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # the laptop closes halfway</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attach</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                              # later: the rest of the output, the end, the results here</span></span></code></pre></div><p>What the <a href="./agents">agents</a> start writes its output to disk where it runs, so a closed laptop or a dropped network loses nothing. The work goes on, and the command here says so before it gives up:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  the connection to the environment was lost: the work goes on over there ( errand attach )</span></span></code></pre></div><p><code>errand attach</code> follows it again: it shows the output from the start, waits for the end, and brings the results back as the command would have. With several left running, it follows each in turn; <code>errand attach ID</code> picks one, by the start of its name ( <code>2026-09-25_18h04m11-cluster</code> ). When the work ended long ago and its output was cleaned up over there, <code>attach</code> still brings back what it wrote in the project.</p><p>This is for commands that go through an environment with layers, which is to say through an agent: another machine, a container, an allocation. A command run here, with no layer, is a child of your terminal and ends with it; Ctrl-C, unlike a lost connection, stops the work everywhere. A <a href="./layers/windows">Windows virtual machine</a> is not followed again yet.</p><h2 id="launch-and-come-back-batch" tabindex="-1">Launch and come back: <code>--batch</code> <a class="header-anchor" href="#launch-and-come-back-batch" aria-label="Permalink to &quot;Launch and come back: \`--batch\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --grid=,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --batch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpu,cluster</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench.py</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  submitted b7f3 - gpu on this machine (local 41288), cluster on login.hpc (batch 918273)</span></span>
<span class="line"><span>  errand status    errand watch</span></span></code></pre></div><p><code>--batch</code> is a <strong>mode, not a layer</strong>: the run is the same, with the same paths, the same queue and the same records. Only the way each place lets go differs:</p><table tabindex="0"><thead><tr><th>place</th><th>you wait</th><th><code>--batch</code></th></tr></thead><tbody><tr><td>here</td><td>a process of this terminal</td><td>a session of its own, which survives the terminal</td></tr><tr><td><code>Ssh</code></td><td>through the agent, output streamed</td><td>started over there and released, output to a file</td></tr><tr><td><code>Slurm</code></td><td>an allocation errand holds, with its agent</td><td><code>sbatch</code>, which returns as soon as the job is queued</td></tr></tbody></table><p>Before giving the shell back, <code>--batch</code> prepares: the target is resolved and built where the environment is, and the <a href="./environments#preparing-then-running">plan</a> comes back here. A mistake in the command is said now, not tomorrow morning. Then the run is submitted, sized from that plan.</p><p><code>--batch</code> does not reach a <a href="./layers/windows">Windows virtual machine</a> yet: it says so for that environment.</p><h2 id="following-a-submission" tabindex="-1">Following a submission <a class="header-anchor" href="#following-a-submission" aria-label="Permalink to &quot;Following a submission&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # what runs everywhere, then each --batch submission</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # the submissions, live, until everything has landed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> b7f3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # drop a submission from the list; its results stay</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> finished</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # drop every one that is over</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>b7f3  run --grid=, --env gpu,cluster python bench.py   2026-09-24 12:04   1/2 [####    ]</span></span>
<span class="line"><span>    gpu: local 41288 on this machine - finished</span></span>
<span class="line"><span>    cluster: batch 918273 on login.hpc - running</span></span></code></pre></div><p>A submission whose results have all landed and come back is <strong>settled</strong>: it is not asked about again, so <code>errand status</code> stays quick however many there are. The settled ones older than a day are counted on one line.</p><p><code>errand watch</code> keeps no state of its own. It reads the tree and asks the batch systems, so it can be stopped, restarted, or run twice. → <a href="./status">What is running</a></p><h2 id="the-output-tree-is-the-state" tabindex="-1">The output tree is the state <a class="header-anchor" href="#the-output-tree-is-the-state" aria-label="Permalink to &quot;The output tree is the state&quot;">​</a></h2><p>Each place writes its plan before anything runs there, so the record of every run has a known path. <strong>A result file arriving where the plan said it would is the completion signal.</strong> Nothing has to stay connected for that, and nothing can get out of sync: the <a href="./output">records</a> every run leaves in <code>errand-outputs/runs/</code> are all there is to follow.</p><p>What is kept here, in <code>errand-outputs/state/</code>, is only what the tree cannot say: which runs belong to one submission, and the handle each place gave ( a pid, a job id ). Only the side that launched them knows they went together.</p><p>A run on another machine, or in a batch job on whichever node the scheduler picked, does not know its machine&#39;s name in advance. Its parameters and its environment are known, so that is what <code>errand status</code> looks for.</p><h2 id="results-come-back-when-you-ask" tabindex="-1">Results come back when you ask <a class="header-anchor" href="#results-come-back-when-you-ask" aria-label="Permalink to &quot;Results come back when you ask&quot;">​</a></h2><p>A finished remote run stays over there until something collects it: <code>errand status</code>, <code>errand watch</code> and <code>errand attach</code> do. → <a href="./sync#results-are-pulled-not-pushed">Results are pulled, not pushed</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./matrices">Several runs: grids</a>.</p>`,29)])])}const u=e(n,[["render",h]]);export{k as __pageData,u as default};
